// Shared vehicle price table (generated by tools/economy/build-prices.mjs from the catalogs; the server reads the same
// JSON). Entry: { price, cls, starter, traffic } — see docs/ECONOMY.md.
import TABLE from './prices.json' with { type: 'json' };
import { exportPool } from './rules.js';

export const PRICES = TABLE;
export const STARTERS = Object.freeze(Object.keys(TABLE).filter((id) => TABLE[id].starter));
export const EXPORT_POOL = Object.freeze(exportPool(TABLE));

/** Price of a catalog id, or null when the id is not in the table. */
export function priceOf(id) {
  return TABLE[id]?.price ?? null;
}

/** Starter car (cheapest compact) and starter bicycle ids. */
export const STARTER_CAR = STARTERS.find((id) => TABLE[id].cls !== 'bicycle') ?? STARTERS[0] ?? 'pip';
export const STARTER_BIKE = STARTERS.find((id) => TABLE[id].cls === 'bicycle') ?? null;
